const input = $input.item.json || {};
const hotelConfig = input.hotelConfig;

if (!hotelConfig) {
  throw new Error("[VALIDACIÓN CRÍTICA]: Falta 'hotelConfig' en los datos de entrada recibidos por el subflujo.");
}

const capacidad = Number(hotelConfig.capacidad_total);
if (!capacidad || isNaN(capacidad) || capacidad <= 0) {
  throw new Error("[VALIDACIÓN CRÍTICA]: 'hotelConfig.capacidad_total' inválida o inexistente.");
}

const schema = hotelConfig.modelo_schema;
if (!Array.isArray(schema) || schema.length === 0) {
  throw new Error("[VALIDACIÓN CRÍTICA]: 'hotelConfig.modelo_schema' no contiene definiciones válidas.");
}

const serie = input.inputModelo || input.contextoNegocioSerie || input.serieDias || input.diario || input.dataOriginal;
if (!Array.isArray(serie) || serie.length === 0) {
  throw new Error("[VALIDACIÓN CRÍTICA]: No se recibió la serie de días para predecir.");
}

function getProp(obj, path) {
  return path.split('.').reduce((acc, part) => (acc !== null && acc !== undefined ? acc[part] : undefined), obj);
}

const inputModelo = serie.map((dia, idx) => {
  // 1. Resolver Fecha obligatoria
  const fechaStr = dia.Fecha || dia.fecha || dia.CheckIn;
  if (!fechaStr) {
    throw new Error(`[VALIDACIÓN CRÍTICA]: El registro ${idx} no contiene 'Fecha'/'CheckIn'.`);
  }

  // 2. Resolver ocupacion_actual obligatoria
  let ocupActual = dia.ocupacion_actual !== undefined ? Number(dia.ocupacion_actual) : undefined;
  if (ocupActual === undefined || isNaN(ocupActual)) {
    const habs = dia.habitaciones_ocupadas ?? dia.rooms_sold;
    if (habs !== undefined && !isNaN(Number(habs))) {
      ocupActual = Number(habs) / capacidad;
    } else {
      throw new Error(`[VALIDACIÓN CRÍTICA]: Falta 'ocupacion_actual' o 'habitaciones_ocupadas' en fecha ${fechaStr}.`);
    }
  }

  // Objeto base con los campos que la Cloud Function audita al inicio
  const fila = {
    Fecha: String(fechaStr).slice(0, 10),
    ocupacion_actual: Number(ocupActual)
  };

  // 3. Procesar resto de variables según modelo_schema
  schema.forEach(def => {
    if (def.variable_modelo === 'Fecha') return;

    const rawVal = getProp(dia, def.origen_dato);

    if (def.tipo === 'numeric') {
      let num = Number(rawVal);
      if (rawVal === undefined || rawVal === null || rawVal === '' || isNaN(num)) {
        if (def.variable_modelo === 'ocupacion_actual') {
          num = ocupActual;
        } else if (def.valor_defecto !== undefined && def.valor_defecto !== '') {
          num = Number(def.valor_defecto);
        } else {
          throw new Error(`[SCHEMA ERROR]: Variable numérica obligatoria '${def.variable_modelo}' no informada en ${fila.Fecha}.`);
        }
      }
      fila[def.variable_modelo] = num;
    } 
    else if (def.tipo.startsWith('one_hot:')) {
      const categoriaEsperada = def.tipo.split(':')[1].trim().toLowerCase();
      const valStr = String(rawVal || '').trim().toLowerCase();
      fila[def.variable_modelo] = valStr.includes(categoriaEsperada) ? 1 : 0;
    } 
    else {
      throw new Error(`[SCHEMA ERROR]: Tipo desconocido '${def.tipo}' para variable '${def.variable_modelo}'.`);
    }
  });

  return fila;
});

return [{
  json: {
    payloadParaAPI: {
      data: inputModelo,
      periodo: input.periodo || `Próximos ${hotelConfig.dias_vista_default} días`,
      hotel_id: hotelConfig.hotel_id
    },
    modelo_endpoint: hotelConfig.modelo_endpoint,
    periodo: input.periodo || `Próximos ${hotelConfig.dias_vista_default} días`,
    hotelConfig,
    dataOriginal: serie,
    contextoNegocioSerie: input.contextoNegocioSerie || serie,
    competenciaResumen: input.competenciaResumen || {}
  }
}];

const datosPrevios = $('Preparar Payload API').item.json;
const respuesta = $input.item.json;
const hotelConfig = datosPrevios.hotelConfig;

// Validación estricta de la respuesta del modelo
if (!respuesta) {
  throw new Error("[VALIDACIÓN CRÍTICA]: La Cloud Function devolvió una respuesta vacía.");
}

const listaResultados = respuesta.resultados || respuesta.predicciones;
if (!Array.isArray(listaResultados) || listaResultados.length === 0) {
  throw new Error(`[VALIDACIÓN CRÍTICA]: La API no devolvió un array de resultados válido. Respuesta: ${JSON.stringify(respuesta)}`);
}

const capacidad = Number(hotelConfig.capacidad_total);
if (!capacidad || isNaN(capacidad) || capacidad <= 0) {
  throw new Error(`[VALIDACIÓN CRÍTICA]: 'hotelConfig.capacidad_total' no válida (${hotelConfig.capacidad_total}).`);
}

// Mapeo sin fallbacks: si falta una métrica crítica, lanza error
const resultadosLimpios = listaResultados.map((r, idx) => {
  const fecha = r.Fecha || r.fecha;
  if (!fecha) {
    throw new Error(`[VALIDACIÓN CRÍTICA]: El resultado en el índice ${idx} no contiene 'Fecha'.`);
  }

  // Comprobar presencia explícita de valores numéricos devueltos
  const ocupAct = r.ocupacion_actual !== undefined ? Number(r.ocupacion_actual) : null;
  const pickup = r.pickup_predicho !== undefined ? Number(r.pickup_predicho) : (r.pickup_previsto !== undefined ? Number(r.pickup_previsto) : null);

  if (pickup === null || isNaN(pickup)) {
    throw new Error(`[VALIDACIÓN CRÍTICA]: 'pickup_predicho' no recibido o no numérico en fecha ${fecha}.`);
  }

  // Ocupación prevista: si viene directa o calculada según pickup proyectado
  let ocupPred = r.ocup_final_predicha !== undefined ? Number(r.ocup_final_predicha) : (r.ocupacion_prevista !== undefined ? Number(r.ocupacion_prevista) : null);

  if (ocupPred === null || isNaN(ocupPred)) {
    if (ocupAct !== null && !isNaN(ocupAct)) {
      // Fórmula de negocio: Ocupación Actual + (Pickup Previsto / Capacidad Total * 100)
      ocupPred = ocupAct + ((Math.max(0, pickup) / capacidad) * 100);
    } else {
      throw new Error(`[VALIDACIÓN CRÍTICA]: No se puede determinar la ocupación prevista para la fecha ${fecha}.`);
    }
  }

  return {
    Fecha: fecha,
    ocupacion_prevista: Number(ocupPred.toFixed(4)),
    ocupacion_actual: ocupAct !== null ? Number(ocupAct.toFixed(4)) : null,
    pickup_previsto: Number(pickup.toFixed(4))
  };
});

return [{
  json: {
    periodo: datosPrevios.periodo,
    resultados: resultadosLimpios,
    hotelConfig,
    dataOriginal: datosPrevios.dataOriginal,
    contextoNegocioSerie: datosPrevios.contextoNegocioSerie,
    competenciaResumen: datosPrevios.competenciaResumen
  }
}];
